      yoyo: +(klemme(r.normal(19, 1.1) + (['AV', 'ZM', 'ZDM', 'FL', 'AM'].indexOf(grund(p.pos)) >= 0 ? 0.6 : 0), 15.5, 22)).toFixed(1),
