    const kopie = d => ({ von: d.von, an: d.an, gibt: { spieler: (d.gibt.spieler || []).slice(), picks: (d.gibt.picks || []).slice() },
      bekommt: { spieler: (d.bekommt.spieler || []).slice(), picks: (d.bekommt.picks || []).slice() } });
