      joinedSeason: (typeof LEAGUE !== 'undefined' && LEAGUE && LEAGUE.season) || 1, pos: p.pos, positions: (p.positions || [p.pos]).slice(),
      def: p.def, mid: p.mid, att: p.att, pace: p.pace, mental: p.mental,
