    const luecke = favoritLuecke(d, i, O, isFinite(naechster) ? naechster : i + 32);
    const lg = H.lage(L, O, H.raenge(L)), capFrei = O.salary_cap_limit - G.capHitTeam(O);
    let faktor = luecke >= 3 ? 1.3 : luecke >= 1.5 ? 1.12 : 1.0;
