  // ── D99: Zu haben (will weg / Abgabe) ────────────────────────────────────
  const ZH_GRUND = { weg: 'will weg', cap: 'Cap-Not', neuaufbau: 'Neuaufbau', stil: 'Stil', ueberschuss: 'Überschuss' };
