    if (eigene.length) melde(`🏅 ${p[eigene[0]].name}: ${H.PREISE[eigene[0]]}!`, `Ein Preis für deinen Verein: ${eigene.map(k => `${H.PREISE[k]} – ${p[k].name}`).join(', ')}.`, 'club');
