    const zu = function () { ov.remove(); dialogAuf = false; };
    ov.addEventListener('click', function (e) {
      if (e.target === ov || e.target.closest('.dfl-frage-nein')) { zu(); return; }
      if (e.target.closest('.dfl-frage-ja')) { zu(); setTimeout(ja, 0); }
    });
