    if (B.hillsLarge) g.drawImage(getoent(B.hillsLarge, ab ? ABEND.fern : k.fern, 0.92), -60, 170, 840, 330);
    if (B.hills) g.drawImage(getoent(B.hills, ab ? ABEND.nah : k.nah, 0.95), -40, 236, 800, 312);
