  // ── Stadtgröße und Anlässe (aus v5 übernommen, Aufräumen 2026-10-13; v5 mit 9 Bildern ist gelöscht) ─────────
  const franchiseFcm = () => { try { return window.DFLSpiel ? DFLSpiel.franchise('fcm') : null; } catch (e) { return null; } };
