          if (v) v.innerHTML = `<b>${(k.capHitJahr(p) / 1e6).toLocaleString('de-DE', { maximumFractionDigits: 1 })}</b>${jahre == null ? '' : jahre <= 0 ? 'endet' : jahre + ' J.'}`;
