        league: LEAGUE, cup: typeof CUP !== 'undefined' ? CUP : null,
        club: { club: CLUB, achievements: typeof FCM_ACHIEVEMENTS !== 'undefined' ? FCM_ACHIEVEMENTS : null, squad: typeof SQUAD !== 'undefined' ? SQUAD : [] },
