      const S = sp(g.top.s), c2 = Object.assign({}, ctx, { spieler: { S }, werte: Object.assign({}, werte, { mal: MAL[g.top.s.n] || g.top.s.n + '-mal', tore: zahlwort(g.top.s.n) }) });
      titel = A0.titel(g.top.s.n >= 4 ? 'titel.viererpack' : 'titel.hattrick', c2);
