    if (danach.length) A0.add(danach.length === 1 ? 'draft.danach.einer' : 'draft.danach', { werte: { liste: liste(danach) } });
    const eig = (d.eigen || [])[0];
    if (eig && eig.nr !== 1) A0.add('draft.eigen', { teams: { E: teamVon(F, F.eigen) }, spieler: { Q: sp(eig.spieler) }, werte: { nr: eig.nr } });
