    const bild = drin ? { art: 'wappen', team: F.eigen } : (eins.length === 2 ? { art: 'duell', a: eins[0], b: eins[1] } : { art: 'liga' });
    if (eins.length === 2) A0.add('po.start.freilos', { teams: { A: teamVon(F, eins[0]), B: teamVon(F, eins[1]) } });
