  function lage() { const Z = W.DFLGelaende && DFLGelaende.v6 && DFLGelaende.v6.zustand && DFLGelaende.v6.zustand(); return Z && Z.lage ? Z.lage : {}; }
  const nacht = () => !!lage().abend;
