      T.offen = { saison: v.saison, label: v.label, lizenz: neueLizenz, wahl: pool };
      news(`${em('🎓 ')}Lehrgang bestanden: ${nxt.name}`, `In der Sommerpause hast du die ${nxt.name} gemacht. Deine Werte können jetzt bis ${nxt.max} steigen.`);
