    const kopf = (t, w) => `<div class="pkf-vp"><span class="pkf-vg">${gesicht(t.p)}</span><b>${esc(voll(t.p))}</b><small>${esc(t.p.pos || '')} · ${t.p.age || '?'} J. · ${esc(wer(t))}</small>${w.klar ? '' : '<span class="pkf-ung">ohne Scout-Bericht: nur die Stufe</span>'}</div>`;
